"""Saved-data subscription controls using the existing workbench components."""
SECTIONS = r'''
<div class="panel" id="dataSubscriptions"><div class="section-head"><h2>数据订阅</h2><button type="button" id="refreshSubscriptions" class="secondary">刷新订阅</button></div>
<p class="help">按条件领取已入库的数据，不会启动搜索。新订阅默认暂停；下载并保存批次后，确认收货才推进进度。</p>
<form id="subscriptionForm"><div class="grid">
<label>订阅名称<input id="subscriptionName" required maxlength="200" placeholder="我的新闻数据"></label>
<label>数据范围<select id="subscriptionScope"><option value="own">本人数据</option><option value="public">公共历史</option><option value="accessible">公共历史与本人</option></select></label>
<label>来源<select id="subscriptionSource"><option value="">全部来源</option><option value="google_web">Google 网页</option><option value="google_news">Google 新闻</option><option value="google_images">Google 图片</option><option value="google_trends">Google 热点</option></select></label>
<label>关键词（可选）<input id="subscriptionQuery" maxlength="300" placeholder="匹配原搜索关键词"></label>
<label>地区（可选）<input id="subscriptionCountry" maxlength="80" placeholder="US"></label>
<label>交付内容<select id="subscriptionMode"><option value="new_urls">新增唯一链接</option><option value="occurrences">每次结果出现记录</option></select></label>
<label>领取起点<select id="subscriptionStart"><option value="now">从现在开始</option><option value="history">补领历史</option></select></label>
<label>历史起始时间（可选）<input id="subscriptionFrom" type="datetime-local" disabled><span class="help">使用当前设备时区；留空补领全部匹配历史。</span></label>
<label>检查间隔<select id="subscriptionInterval"><option value="3600">每小时</option><option value="86400">每天</option><option value="60">每分钟</option></select></label>
</div><button>保存为暂停订阅</button></form>
<p class="help">新增链接按本订阅已确认的 URL 去重。完整请求保留上下文，实际新增项以 events 为准。从现在开始：排除创建时已存在的匹配数据；补领历史：从最早匹配记录开始。暂停期间的新增数据会保留待领取。</p>
<div id="subscriptionList" aria-live="polite"><p class="product-empty">连接客户空间后查看订阅。</p></div>
<div id="subscriptionBatch" aria-live="polite"></div><div id="subscriptionHistory" aria-live="polite"></div></div>
'''
JS = r'''
let subscriptionBatches=new Map(),subscriptionCreateIntent=null,subscriptionRequestVersion=0,subscriptionSessionVersion=0,subscriptionLoadedKey=null,subscriptionHistoryState=null,subscriptionHistoryVersion=0,subscriptionBatchVersion=0;
function clearSubscriptionSession(){subscriptionHistoryVersion++;subscriptionBatchVersion++;subscriptionSessionVersion++;subscriptionRequestVersion++;subscriptionLoadedKey=null;subscriptionCreateIntent=null;subscriptionBatches.clear();$('subscriptionBatch').innerHTML='';$('subscriptionHistory').innerHTML='';subscriptionHistoryState=null;$('subscriptionList').innerHTML=productEmpty('连接客户空间后刷新订阅。');}
$('connectForm').addEventListener('submit',clearSubscriptionSession,true);$('disconnectKey').addEventListener('click',clearSubscriptionSession,true);
async function subscriptionApi(path,payload){const key=productKey,sessionVersion=subscriptionSessionVersion,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch(path,{method:payload===undefined?'GET':'POST',signal:controller.signal,headers:{Authorization:'Bearer '+key,...(payload===undefined?{}:{'Content-Type':'application/json'}),...(path==='/v1/data/subscriptions'&&payload!==undefined?{'Idempotency-Key':subscriptionCreateIntent.key}:{})},...(payload===undefined?{}:{body:JSON.stringify(payload)})});const d=await r.json();if(productKey!==key||subscriptionSessionVersion!==sessionVersion)throw Error('客户空间已切换，请刷新订阅');if(!r.ok)throw Error(d.error||'请求失败 '+r.status);return d;}catch(e){if(e.name==='AbortError')throw Error('等待超时。操作可能已保存，请刷新；重复提交会复用同一幂等标识。');throw e;}finally{clearTimeout(timer);}}
async function loadSubscriptions(){subscriptionHistoryVersion++;subscriptionBatchVersion++;const key=productKey,version=++subscriptionRequestVersion;$('subscriptionBatch').innerHTML='';$('subscriptionHistory').innerHTML='';subscriptionHistoryState=null;subscriptionBatches.clear();if(!key){$('subscriptionList').innerHTML=productEmpty('连接客户空间后查看订阅。');return;}$('subscriptionList').innerHTML=productEmpty('正在读取订阅…');try{const d=await subscriptionApi('/v1/data/subscriptions');if(key!==productKey||version!==subscriptionRequestVersion)return;subscriptionLoadedKey=key;$('subscriptionList').innerHTML=d.subscriptions.length?productTable(['名称 / 条件','起点 / 最近确认','状态','操作'],d.subscriptions.map(x=>`<tr><td>${esc(x.name)}<div class="help">${esc([x.filters.scope||'own',x.filters.source||'全部来源',x.filters.query||'',x.filters.country||''].filter(Boolean).join(' / '))}</div></td><td>${x.start_mode==='now'?'从创建时开始':'补领历史'}<div class="help">${x.last_acknowledged_at?time(x.last_acknowledged_at):'尚未确认'}</div><div class="help">${x.mode==='new_urls'?'新增唯一链接':'结果出现记录'}</div></td><td>${x.active?'可拉取':'已暂停'}</td><td><div class="product-row"><button type="button" class="mini secondary" data-sub="${esc(x.id)}" data-action="${x.active?'pause':'resume'}">${x.active?'暂停':'继续'}</button><button type="button" class="mini" data-sub="${esc(x.id)}" data-action="pull">领取待确认批次</button><button type="button" class="mini secondary" data-sub="${esc(x.id)}" data-action="progress">进度与交付记录</button></div></td></tr>`)):productEmpty('尚无订阅。保存条件后，订阅会保持暂停。');}catch(e){if(key===productKey&&version===subscriptionRequestVersion)$('subscriptionList').textContent=e.message+' 点击“刷新订阅”重试。';}}
$('refreshSubscriptions').onclick=loadSubscriptions;
$('subscriptionStart').onchange=()=>{$('subscriptionFrom').disabled=$('subscriptionStart').value!=='history';};
$('subscriptionForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;if(!productKey){notice('先连接客户空间',true);return;}const filters={scope:$('subscriptionScope').value};for(const [id,name] of [['subscriptionSource','source'],['subscriptionQuery','query'],['subscriptionCountry','country']]){const v=$(id).value.trim();if(v)filters[name]=v;}if($('subscriptionStart').value==='history'&&$('subscriptionFrom').value)filters.from=new Date($('subscriptionFrom').value).toISOString();const payload={start_mode:$('subscriptionStart').value,name:$('subscriptionName').value.trim(),filters,mode:$('subscriptionMode').value,interval_seconds:Number($('subscriptionInterval').value)},hash=JSON.stringify(payload);if(!subscriptionCreateIntent||subscriptionCreateIntent.hash!==hash||subscriptionCreateIntent.owner!==productKey)subscriptionCreateIntent={hash,key:crypto.randomUUID(),owner:productKey};b.disabled=true;try{await subscriptionApi('/v1/data/subscriptions',payload);subscriptionCreateIntent=null;notice('订阅已保存，当前暂停');await loadSubscriptions();}catch(e){notice(e.message,true);}finally{b.disabled=false;}};
$('subscriptionList').onclick=async e=>{const b=e.target.closest('button[data-sub]');if(!b)return;b.disabled=true;const sid=b.dataset.sub,action=b.dataset.action,batchVersion=action==='pull'?++subscriptionBatchVersion:subscriptionBatchVersion;try{if(action==='progress'){await showSubscriptionHistory(sid);return;}const d=await subscriptionApi('/v1/data/subscriptions/'+sid+'/'+action,{});if(action!=='pull'){await loadSubscriptions();return;}if(batchVersion!==subscriptionBatchVersion)return;if(!d.batch_id){$('subscriptionBatch').textContent=d.reason==='interval_not_elapsed'?'尚未到下次检查时间：'+time(d.next_poll_at):'当前没有待交付的新记录。下次检查：'+time(d.next_poll_at);return;}renderSubscriptionBatch(sid,d);}catch(e){notice(e.message,true);}finally{b.disabled=false;}};
function renderSubscriptionBatch(sid,d){subscriptionBatchVersion++;subscriptionBatches.clear();subscriptionBatches.set(sid,{...d,owner:productKey,downloaded:false});$('subscriptionBatch').innerHTML=`<h3>${d.acknowledged_at?'已确认批次':d.discarded_at?'已丢弃批次':'待确认批次'}</h3><p>${d.payload.request_count} 个完整请求 · ${d.payload.event_count} 个交付事件${d.payload.has_more?' · 后续还有数据':''}</p><p class="help" style="overflow-wrap:anywhere">批次 ${esc(d.batch_id)}<br>SHA256：${esc(d.sha256)}</p><div class="product-row"><button type="button" class="secondary" data-download="jsonl" data-sub="${esc(sid)}">下载完整 JSONL</button><button type="button" class="secondary" data-download="csv" data-sub="${esc(sid)}">下载完整 CSV</button><button type="button" class="secondary" data-download="manifest" data-sub="${esc(sid)}">下载校验清单</button><button type="button" data-ack="${esc(sid)}" disabled>${d.acknowledged_at?'已确认收货':d.discarded_at?'已丢弃':'下载后确认收货'}</button></div><p class="help">确认表示已自行保存文件；浏览器无法证明文件已写入磁盘。未确认时重复领取返回同一批；切换批次后需重新下载，才能确认当前批次。</p>`;}
$('subscriptionBatch').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const sid=b.dataset.sub||b.dataset.ack,batch=subscriptionBatches.get(sid);if(!batch||batch.owner!==productKey)return;const batchVersion=subscriptionBatchVersion;b.disabled=true;try{if(b.dataset.download){const key=productKey,sessionVersion=subscriptionSessionVersion,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);let blob;try{const r=await fetch('/v1/data/subscriptions/'+sid+'/batches/'+batch.batch_id+'/export?format='+b.dataset.download,{headers:{Authorization:'Bearer '+key},signal:controller.signal});if(!r.ok)throw Error('下载失败 '+r.status);blob=await r.blob();}finally{clearTimeout(timer);}if(key!==productKey||sessionVersion!==subscriptionSessionVersion||batchVersion!==subscriptionBatchVersion||subscriptionBatches.get(sid)!==batch)return;const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=batch.batch_id+'.'+b.dataset.download;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(b.dataset.download!=='manifest'){batch.downloaded=true;if(!batch.acknowledged_at&&!batch.discarded_at)$('subscriptionBatch').querySelector('[data-ack]').disabled=false;}}else if(b.dataset.ack&&batch.downloaded&&!batch.acknowledged_at&&!batch.discarded_at){await subscriptionApi('/v1/data/subscriptions/'+sid+'/batches/'+batch.batch_id+'/ack',{sha256:batch.sha256});notice('已确认收货，可继续领取后续数据');await loadSubscriptions();}}catch(e){notice(e.name==='AbortError'?'下载超时，请重试同一批次':e.message,true);}finally{if(b.isConnected)b.disabled=false;}};
function renderSubscriptionHistory(){const h=subscriptionHistoryState;if(!h||h.owner!==productKey)return;const d=h.status;$('subscriptionHistory').innerHTML=`<h3>订阅进度</h3><div class="product-statline"><div><strong>${fmt(d.remaining_requests)}</strong><small>待处理请求（含待确认批次）</small></div><div><strong>${fmt(d.delivery.acknowledged_requests)}</strong><small>已确认请求</small></div><div><strong>${fmt(d.delivery.acknowledged_events)}</strong><small>已确认交付事件</small></div></div><p class="help">最近确认：${d.delivery.last_acknowledged_at?time(d.delivery.last_acknowledged_at):'尚未确认'} · 批次存储 ${fmt(d.delivery.stored_payload_bytes)} 字节 · 统计时间 ${time(d.generated_at)}</p><h3>交付记录</h3>`+(h.rows.length?productTable(['批次 / 创建时间','数量','状态','操作'],h.rows.map(x=>`<tr><td>${esc(x.id)}<div class="help">${time(x.created_at)}</div></td><td>${fmt(x.request_count)} 请求 / ${fmt(x.event_count)} 事件</td><td>${({pending:'待确认',acknowledged:'已确认',discarded:'已丢弃'})[x.state]}</td><td><button type="button" class="mini secondary" data-history-batch="${esc(x.id)}" data-sub="${esc(h.sid)}">查看与重新下载</button></td></tr>`)):productEmpty('还没有交付批次。'))+(h.cursor?'<button type="button" class="secondary" data-history-more="true">更多记录</button>':'');}
async function showSubscriptionHistory(sid){const key=productKey,version=++subscriptionHistoryVersion;subscriptionHistoryState=null;$('subscriptionHistory').textContent='正在读取进度与交付记录…';const [status,history]=await Promise.all([subscriptionApi('/v1/data/subscriptions/'+sid+'/status'),subscriptionApi('/v1/data/subscriptions/'+sid+'/batches?limit=10')]);if(key!==productKey||version!==subscriptionHistoryVersion)return;subscriptionHistoryState={sid,owner:key,status,rows:history.batches,cursor:history.next_cursor};renderSubscriptionHistory();}
$('subscriptionHistory').onclick=async e=>{const b=e.target.closest('button'),h=subscriptionHistoryState;if(!b||!h||h.owner!==productKey)return;b.disabled=true;try{if(b.dataset.historyMore){const d=await subscriptionApi('/v1/data/subscriptions/'+h.sid+'/batches?limit=10&cursor='+encodeURIComponent(h.cursor));if(h!==subscriptionHistoryState)return;h.rows.push(...d.batches);h.cursor=d.next_cursor;renderSubscriptionHistory();}else if(b.dataset.historyBatch){const version=++subscriptionBatchVersion;const d=await subscriptionApi('/v1/data/subscriptions/'+b.dataset.sub+'/batches/'+b.dataset.historyBatch);if(h!==subscriptionHistoryState||version!==subscriptionBatchVersion)return;renderSubscriptionBatch(b.dataset.sub,d);$('subscriptionBatch').scrollIntoView({block:'nearest'});}}catch(e){notice(e.message,true);}finally{if(b.isConnected)b.disabled=false;}};
const subscriptionLoadCustomer=loadCustomer;loadCustomer=async function(){await subscriptionLoadCustomer();if(subscriptionLoadedKey!==productKey)await loadSubscriptions();};
'''
